W, H, T, D, inset := 80.0, 50.0, 6.0, 6.0, 10.0
sides := doc.Sketch.Rect(V(0, 0, 0), V(W, H, 0))
doc.Constrain.Coincident(sides[0].Start(), doc.Origin())
doc.Constrain.Length(sides[0], W)
doc.Constrain.Length(sides[1], H)
xs := []float64{inset, W - inset}
ys := []float64{inset, H - inset}
for _, x := range xs {
	for _, y := range ys {
		h := doc.Sketch.Circle(V(x, y, 0), D/2)
		doc.Constrain.Diameter(h, D)
		if x < W/2 {
			doc.Constrain.Distance(h.Center(), sides[3], inset)
		} else {
			doc.Constrain.Distance(h.Center(), sides[1], inset)
		}
		if y < H/2 {
			doc.Constrain.Distance(h.Center(), sides[0], inset)
		} else {
			doc.Constrain.Distance(h.Center(), sides[2], inset)
		}
	}
}
